def _vdir(ws: Path) -> Path:
    return ws / "verification"


DELTA_ASSETS = "verification/delta"  # v2 D1: delta tests, same format, own directory


def _assets_dir(ws: Path, assets: str | None) -> Path:
    """Where the test assets are: verification/, or a directory under it (v2 D1)."""
    if not assets:
        return _vdir(ws)
    root = (ws / assets).resolve()
    if _vdir(ws).resolve() not in root.parents:
        raise VerifyError(f"assets must be a directory under verification/, got {assets!r}")
    return root


def assets_digest(ws: Path, assets: str | None) -> str:
    """What a verdict was computed on: a later change of the tests makes it stale."""
    root = _assets_dir(ws, assets)
    h = hashlib.sha256()
    for p in sorted(q for d in ("events", "faults") if (root / d).is_dir() for q in (root / d).rglob("*.json")):
        h.update(p.relative_to(root).as_posix().encode())
        h.update(p.read_bytes())
    return h.hexdigest()[:16]


def load_cases(ws: Path, assets: str | None = None) -> list[dict[str, Any]]:
    out = []
    for p in sorted((_assets_dir(ws, assets) / "events").glob("*/*.json")):
        try:
            case = _read_json(p)
        except json.JSONDecodeError as exc:
            case = {"_load_error": f"invalid JSON: {exc}"}
        if isinstance(case, dict):
            case["_file"] = str(p.relative_to(ws)).replace("\\", "/")
            case.setdefault("id", p.stem)
            case.setdefault("function", p.parent.name)
        out.append(case)
    return out


def load_faults(ws: Path, assets: str | None = None) -> list[dict[str, Any]]:
    out = []
    for p in sorted((_assets_dir(ws, assets) / "faults").glob("*.json")):
        try:
            f = _read_json(p)
        except json.JSONDecodeError as exc:
            f = {"_load_error": f"invalid JSON: {exc}"}
        if isinstance(f, dict):
            f["_file"] = str(p.relative_to(ws)).replace("\\", "/")
            f.setdefault("id", p.stem)
        out.append(f)
    return out


_SPEC_REF_RE = re.compile(r"^(GET|POST|PUT|DELETE|PATCH) (\S+)#(request|responses|business_rules|auth|data_access)(?:\[(\d+)\])?(?:\.\S+)?$")


def _check_spec_ref(model: Model, ref: str) -> str | None:
    res = re.match(r"^blueprint:metadata\.spec_resolutions\[([^\]]+)\]", ref)
    if res:
        ids = [r.get("issue_id") for r in (model.blueprint.get("metadata", {}) or {}).get("spec_resolutions", []) or [] if isinstance(r, dict)]
        return None if res.group(1) in ids else f"spec_ref {ref!r}: blueprint metadata.spec_resolutions has no issue_id {res.group(1)!r} (has {ids})"
    if ref.startswith("blueprint:"):
        return None
    m = _SPEC_REF_RE.match(ref)
    if not m:
        return (f"spec_ref {ref!r} must look like 'POST /api/orders#business_rules[2]' "
                f"(field one of request/responses/business_rules/auth/data_access) or start with 'blueprint:'")
    method, path, field, idx = m.groups()
    ep = next((e for e in model.analysis.get("entry_points", []) if e.get("method") == method and e.get("path") == path), None)
    if ep is None:
        return f"spec_ref {ref!r}: no entry point {method} {path} in analysis_report.json"
    if idx is not None:
        val = ep.get(field)
        if not isinstance(val, list) or int(idx) >= len(val):
            return f"spec_ref {ref!r}: {field} has {len(val) if isinstance(val, list) else 0} items"
    return None


def check_case(model: Model, case: dict[str, Any], with_template: bool) -> list[str]:
    """Schema and name checks for one case; no execution."""
    where = case.get("_file", case.get("id", "?"))
    if "_load_error" in case:
        return [f"{where}: {case['_load_error']}"]
    errs: list[str] = []
    allowed = {"id", "function", "kind", "title", "spec_refs", "request", "sqs", "fixtures", "faults", "expect", "note", "repeat",
               "source", "expected_from", "_file"}
    extra = set(case) - allowed
    if extra:
        errs.append(f"{where}: unknown keys {sorted(extra)} (allowed: {sorted(allowed - {'_file'})})")
    fn_name = case.get("function")
    if fn_name not in model.bp_functions:
        errs.append(f"{where}: function {fn_name!r} is not a blueprint lambda_functions name ({sorted(model.bp_functions)})")
        return errs
    bp_fn = model.bp_functions[fn_name]
    if case.get("kind") not in CASE_KINDS:
        errs.append(f"{where}: kind must be one of {CASE_KINDS}")
    refs = case.get("spec_refs")
    if not isinstance(refs, list) or not refs:
        errs.append(f"{where}: spec_refs must be a non-empty list")
    else:
        errs += [f"{where}: {e}" for r in refs if (e := _check_spec_ref(model, str(r)))]
    trigger = bp_fn.get("trigger_type")
    if trigger == "api":
        req = case.get("request")
        if not isinstance(req, dict) or not req.get("method") or not req.get("path"):
            errs.append(f"{where}: api functions need request {{method, path, query?, headers?, body?, identity?}}")
        else:
            bad = set(req) - {"method", "path", "query", "headers", "body", "identity"}
            if bad:
                errs.append(f"{where}: request has unknown keys {sorted(bad)}")
            ident = req.get("identity")
            if ident is not None and (not isinstance(ident, dict) or not ident.get("sub")):
                errs.append(f"{where}: request.identity must be null (anonymous) or an object with at least 'sub'")
            eps = [e.split(" ", 1) for e in bp_fn.get("entry_points") or [] if isinstance(e, str) and " " in e]
            if not any(m.upper() == str(req["method"]).upper() and _path_match(p, str(req["path"])) is not None for m, p in eps):
                errs.append(f"{where}: {req['method']} {req['path']} does not match any entry point of {fn_name} {bp_fn.get('entry_points')}")
    elif trigger == "sqs":
        sqs = case.get("sqs")
        if not isinstance(sqs, dict) or not isinstance(sqs.get("records"), list) or not sqs["records"]:
            errs.append(f"{where}: sqs functions need sqs {{records: [{{body, message_id?}}, ...]}}")
    fixtures = case.get("fixtures", {})
    if not isinstance(fixtures, dict):
        errs.append(f"{where}: fixtures must be an object {{Table: [items]}}")
    else:
        for t, items in fixtures.items():
            errs += _name_err(model, where, "fixtures", t, "table", with_template)
            if not isinstance(items, list) or not all(isinstance(i, dict) for i in items):
                errs.append(f"{where}: fixtures.{t} must be a list of items")
    if "repeat" in case and not (isinstance(case["repeat"], int) and not isinstance(case["repeat"], bool) and 2 <= case["repeat"] <= 5):
        errs.append(f"{where}: repeat must be an integer 2..5 (the same request that many times in one execution environment)")
    if "faults" in case:
        errs += _check_rules(model, where, case["faults"], with_template)
    errs += _check_expect(model, where, case.get("expect"), trigger, with_template)
    if isinstance(case.get("expect"), dict) and "alternatives" in case["expect"] and not _si_refs(case):
        errs.append(f"{where}: expect.alternatives is only allowed in a case whose spec_refs cite a "
                    "blueprint:metadata.spec_resolutions[SI-x] ruling that allows more than one outcome")
    return errs


_DELTA_SOURCE_RE = re.compile(r"^(GAP-\d+|rule:.+)$")
_EXPECTED_FROM_RE = re.compile(r"^(monolith|ruling|rulebook|decision):(.+)$")


def _as_list(value: Any) -> list[Any]:
    return value if isinstance(value, list) else [value]


def _expected_from_errors(ws: Path, where: str, case: dict[str, Any], gaps_by_id: dict[str, Any],
                          oracle: dict[str, Any], ruling_ids: set[str]) -> list[str]:
    """expected_from names where a delta test's expectation comes from (V2-08), and the
    name must resolve. A status taken from the monolith must be the status it answered."""
    raw = case.get("expected_from")
    m = _EXPECTED_FROM_RE.match(raw) if isinstance(raw, str) else None
    if not m:
        return [f"{where}: expected_from must be 'monolith:<judge case>/<step>', 'ruling:<id>', 'rulebook:<rule>' or 'decision:GAP-<n>', got {raw!r}"]
    kind, ref = m.groups()
    if kind == "decision":
        return [] if ref in gaps_by_id else [f"{where}: expected_from {raw!r}: no such gap in storage/gap_inventory.json"]
    if kind == "ruling":
        return [] if ref in ruling_ids else [f"{where}: expected_from {raw!r}: no such ruling in storage/rulings.json"]
    if kind == "rulebook":
        return []
    judge_case, _, step = ref.partition("/")
    steps = ((oracle.get("cases") or {}).get(judge_case) or {}).get("steps") or {}
    if step not in steps:
        return [f"{where}: expected_from {raw!r}: judge/oracle_expected.json has no case/step like that (case {judge_case!r} has steps {sorted(steps)})"]
    expect = case.get("expect") if isinstance(case.get("expect"), dict) else {}
    answered = (steps[step] or {}).get("status")
    if "status" in expect and answered is not None and expect["status"] != answered:
        return [f"{where}: expected_from {raw!r}: the monolith answered {answered} there, the case expects {expect['status']}"]
    return []


def delta_errors(ws: Path, cases: list[dict[str, Any]]) -> list[str]:
    """The checks of delta tests beyond the v1 case format: every case says which gap or
    rule it tests and where its expectation comes from, and every gap decided with
    test: "delta" has a case."""
    import gaps

    inventory = gaps.load(ws) or {}
    by_id = {g.get("id"): g for g in inventory.get("gaps") or [] if isinstance(g, dict)}
    oracle_path = ws / "judge" / "oracle_expected.json"
    oracle = _read_json(oracle_path) if oracle_path.is_file() else {}
    rulings_path = ws / "storage" / "rulings.json"
    rulings = (_read_json(rulings_path) if rulings_path.is_file() else {}).get("rulings") or []
    ruling_ids = {str(r.get("id")) for r in rulings if isinstance(r, dict)}
    errs: list[str] = []
    cited: set[str] = set()
    for case in cases:
        if "_load_error" in case:
            continue
        where = case.get("_file", case.get("id", "?"))
        sources = _as_list(case.get("source"))
        if not case.get("source") or not all(isinstance(s, str) and _DELTA_SOURCE_RE.match(s) for s in sources):
            errs.append(f"{where}: source must be 'GAP-<n>' or 'rule:<rule>' (or a list of them), got {case.get('source')!r}")
            continue
        for s in sources:
            if s.startswith("GAP-"):
                cited.add(s)
                if s not in by_id:
                    errs.append(f"{where}: source {s} is not in storage/gap_inventory.json")
        errs += _expected_from_errors(ws, where, case, by_id, oracle, ruling_ids)
    for g in gaps.delta_gaps(ws):
        if g.get("id") not in cited:
            errs.append(f"{g.get('id')} is decided with test: delta, and no delta test cites it as its source")
    return errs


def _si_refs(case: dict[str, Any]) -> list[str]:
