import json, glob, os
# final consistency sweep: every case must be valid JSON, have the required fields, and no forbidden keys
allowed_case={"id","function","kind","title","spec_refs","request","sqs","fixtures","faults","expect","note","repeat","source","expected_from"}
bad=[]
rows=[]
for f in sorted(glob.glob('events/*/*.json')):
    c=json.load(open(f,encoding='utf-8'))
    extra=set(c)-allowed_case
    if extra: bad.append((f,sorted(extra)))
    for k in ("id","function","kind","spec_refs","source","expected_from","expect"):
        if k not in c: bad.append((f,'missing '+k))
    if c.get('id')!=os.path.basename(f)[:-5]: bad.append((f,'id != filename'))
    rows.append((c['function'],c['id'],c['kind'],c['expected_from'],';'.join(c['source'])))
for f in sorted(glob.glob('faults/*.json')):
    d=json.load(open(f,encoding='utf-8'))
    if d.get('id')!=os.path.basename(f)[:-5]: bad.append((f,'id != filename'))
    if not set(d)>= {"id","description","function","cases","rules"}: bad.append((f,'missing keys '+str(set(d))))
    for cid in d['cases']:
        if not glob.glob('events/*/'+cid+'.json'): bad.append((f,'unknown case '+cid))
print('PROBLEMS:',bad if bad else 'none')
print()
