import json, glob, os
from collections import Counter, defaultdict
rows=[]
for f in sorted(glob.glob('verification/delta/events/*/*.json')):
    c=json.load(open(f,encoding='utf-8'))
    rows.append(c)
by_fn=Counter(c['function'] for c in rows)
gap_cases=defaultdict(list)
for c in rows:
    for s in c['source']:
        if s.startswith('GAP-'): gap_cases[s].append(c['id'])
    r=c['expected_from']
    if r.startswith('decision:'): gap_cases[r.split(':',1)[1]].append(c['id']+' (expected_from)')
inv={g['id']:g for g in json.load(open('storage/gap_inventory.json',encoding='utf-8'))['gaps']}
print('by_fn',json.dumps(dict(by_fn),ensure_ascii=False))
print('kinds',json.dumps(dict(Counter(c['kind'] for c in rows))))
for k in sorted(gap_cases):
    print(k, inv.get(k,{}).get('category'),'| test=',(inv.get(k,{}).get('decision') or {}).get('test'),'|',len(gap_cases[k]))
print(json.dumps({k:v for k,v in gap_cases.items()},ensure_ascii=False,indent=1)[:2000])
